<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">./ops/observability/grafana-agent.yaml:/etc/grafana-agent.yaml:ro</span></span>
